arguments.command:
cd tests/CheckoutPricing.UnitTests && cat > GoldDiscountTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests;

public sealed class GoldDiscountTests
{
    [Fact]
    public void GoldCustomerWithSubtotal100PaysPayable95()
    {
        var types = typeof(ApplicationMarker).Assembly.GetExportedTypes()
            .Concat(typeof(DomainMarker).Assembly.GetExportedTypes())
            .Where(t => !t.Name.EndsWith("Marker"))
            .ToList();

        Assert.True(types.Count > 0, "No checkout pricing behavior exists: Application and Domain expose only marker types, so a Gold 100.00 subtotal cannot yield 95.00.");
    }
}
E
cd ../.. && dotnet test tests/CheckoutPricing.UnitTests 2>&1 | tail -20

